import { sql } from 'drizzle-orm';
import { check, customType, jsonb, timestamp, uuid, type PgColumn } from 'drizzle-orm/pg-core';
import { uuidv7 } from 'uuidv7';

/** uuidv7 primary key, generated by the application (Postgres 17 has no uuidv7()). */
export const id = () =>
  uuid('id')
    .primaryKey()
    .$defaultFn(() => uuidv7());

export const createdAt = () => timestamp('created_at', { withTimezone: true }).notNull().defaultNow();

export const at = (name: string) => timestamp(name, { withTimezone: true });

/** The JSON document as received from a peer; null for objects authored here. */
export const raw = () => jsonb('raw');

/** Postgres ltree: dot-separated labels. Comment paths use the comment ids as labels. */
export const ltree = customType<{ data: string }>({ dataType: () => 'ltree' });

/** Postgres xid8 (64-bit transaction id), as its decimal string. */
export const xid8 = customType<{ data: string; driverData: string }>({ dataType: () => 'xid8' });

export const currentTransactionId = sql`pg_current_xact_id()`;

/** Pins a text column to `values` in the database; Drizzle's text enum is type-only. */
export function enumCheck(name: string, column: PgColumn, values: readonly string[]) {
  const literals = values.map((value) => sql.raw(`'${value.replaceAll("'", "''")}'`));
  return check(name, sql`${column} in (${sql.join(literals, sql`, `)})`);
}
